import { Router } from '@marmeon/router';
import { createHttpKernel } from '@marmeon/server';
import { createTestApp, type TestApp } from '@marmeon/testing';
import { beforeEach, describe, expect, it } from 'vitest';
import application from '../../bootstrap/app.ts';
import { UserFactory } from './factories/UserFactory.ts';
import { VerifyEmailMail } from './mail/VerifyEmailMail.ts';

// Generated by `marmeon make:auth` — the rate limits of this module's routes.

// Guest routes that are not this module's: they hold no account and no secret to guess. Anything else that changes something for a guest
// needs a throttle of its own.
const OUTSIDE_THE_MODULE: RegExp[] = [
  /^\/locale$/, // the language picker
  /^\/_marmeon\/uploads\//, // the framework's upload target: a signed address, checked before the file is read
];

let app: TestApp;
beforeEach(async () => {
  app = await createTestApp(application, { database: 'refresh' });
}, 30_000);

describe('the limits of the auth routes', { timeout: 30_000 }, () => {
  it('puts a throttle on every route that changes something and that a guest can reach', () => {
    const router = app.make(Router);
    const names = (route: (typeof router.routes)[number]) => router.middlewareFor(route).map((middleware) => (middleware as { name: string }).name);
    const guestPosts = router.routes.filter((route) => route.methods.some((method) => method !== 'GET' && method !== 'HEAD') && !names(route).some((name) => name.startsWith('authenticate')) && !OUTSIDE_THE_MODULE.some((path) => path.test(route.path)));
    // The guest routes of the module are among them: a test that finds none would pass for nothing.
    expect(guestPosts.map((route) => route.path)).toEqual(expect.arrayContaining(['/login', '/register', '/forgot-password', '/reset-password', '/two-factor-challenge', '/passkeys/sign-in']));
    const unthrottled = guestPosts.filter((route) => !names(route).some((name) => name.startsWith('throttle:'))).map((route) => `${route.methods.join(',')} ${route.path}`);
    expect(unthrottled).toEqual([]);
  });

  it('answers the eleventh code of a minute from one client with 429', async () => {
    const kernel = createHttpKernel(app.application);
    const post = (remote: string) => kernel.request('/two-factor-challenge', { method: 'POST', headers: { accept: 'application/json', 'content-type': 'application/json' }, body: JSON.stringify({ code: '000000' }) }, { remoteAddress: remote });
    const statuses = [];
    for (let i = 0; i < 11; i++) statuses.push((await post('203.0.113.50')).status);
    expect(statuses.slice(0, 10)).not.toContain(429);
    expect(statuses[10]).toBe(429);
    expect((await post('203.0.113.51')).status).not.toBe(429);
  });

  it('sends ten links a day at most, and five an hour to one address', async () => {
    const kj = await app.factory(UserFactory).state('unverified').create();
    const resend = () => app.actingAs(kj).post('/email/verification-notification');
    // Five mails within the first hour; the sixth request answers alike and queues nothing.
    for (let i = 0; i < 6; i++) {
      (await resend()).assertRedirect();
      app.travel({ seconds: 61 });
    }
    app.mail.assertQueuedCount(VerifyEmailMail, 5);
    // The next hour: four more requests make the day's tenth (the refused one counts too), and the eleventh is turned away.
    app.travel({ hours: 1 });
    for (let i = 0; i < 4; i++) {
      (await resend()).assertRedirect();
      app.travel({ seconds: 61 });
    }
    app.mail.assertQueuedCount(VerifyEmailMail, 9);
    await resend().then((response) => response.assertStatus(429));
  });
});
